import json
from pathlib import Path
S={
'xian':('西安','XIAN','陕西历史博物馆','陕西历史博物馆','综合历史馆','https://www.sxhm.com/','西安市雁塔区小寨东路91号','把长安的光，藏进一次凝视','从秦的制度到唐的日常，沿着金属、石材与器形，读懂古都的不同侧面。'),
'shanghai':('上海','SHANGHAI','上海博物馆','上海博物馆','综合艺术馆','https://www.shanghaimuseum.net/','上海市黄浦区人民大道201号（人民广场馆）；浦东新区世纪大道1952号（东馆）','从一行铭文，走进一段历史','用鼎、盘与量器串起一条观看线索：器物既有形状，也保存着人的名字与制度的痕迹。'),
'suzhou':('苏州','SUZHOU','苏州博物馆','苏州博物馆','地方历史艺术馆','https://www.szmuseum.com/','苏州市姑苏区东北街204号（本馆）','让江南的细节，慢慢显影','从瓷器的釉色、宝幢的结构到银器的日常用途，认识吴地工艺与生活。'),
'wuhan':('武汉','WUHAN','湖北省博物馆','湖北省博物馆','综合历史馆','https://www.hbww.org.cn/','武汉市武昌区东湖路160号','在荆楚，读懂金石的回声','一把剑、一套钟、一组尊盘。循着纹饰、声音与结构，进入先秦工艺的世界。'),
'zhengzhou':('郑州','ZHENGZHOU','河南博物院','河南博物院','综合历史馆','https://www.chnmus.net/','郑州市金水区农业路8号','在中原，看见时间的层次','从骨笛到青铜器，不急着跨越所有年代。先挑一个细节，让远古的创造变得具体。'),
'changsha':('长沙','CHANGSHA','湖南博物院','湖南博物院','综合历史馆','https://web.hnmuseum.com/','长沙市开福区东风路50号','在轻纱与漆色中，遇见汉代','把目光放慢，观看马王堆出土的丝织品、帛画与漆木器。材料也能成为理解历史的入口。')}
A=[]
def add(id,m,title,period,material,intro,body,look,url,quiz,options,answer,remarks=''):
 A.append(dict(id=id,museum=m,city=S[m][0],title=title,period=period,material=material,cover=id,gallery=[id],category=material,label='馆藏文物资料',intro=intro,body=body,look=look,source={'title':S[m][3]+' · '+title,'url':url},tags=[period,material,S[m][0]],sourceRemarks=remarks or '本条为馆藏知识介绍，资料图片不构成当天展出的承诺；原件、复制件及展陈位置以馆方现场说明为准。',quiz={'question':quiz,'options':options,'answer':answer,'explain':look},steps=['先看整体轮廓与材料。','再带着观察提示找一个细节。','对照展签与来源，记录自己的问题。'],audioText=title+'。'+intro+body+'观看时，'+look))
add('agate-cup','xian','镶金兽首玛瑙杯','唐','玛瑙、金','石材自己的纹路，也参与了器物的设计。','杯体以缠丝玛瑙雕成，前端为兽首，兽嘴处的金塞可以取下。馆方介绍将这种器形与“来通”酒具联系起来，同时明确其产地仍有学术争议。','先找玛瑙的色带，再看色带如何顺着杯体与兽首展开。不要把关于产地的推测当成定论。','https://www.sxhm.com/collections/detail/512.html','这件杯子的主要材料是什么？',['玛瑙','白瓷','竹'],0)
add('du-tally','xian','错金杜虎符','秦','青铜、错金','一只小虎，保存着调兵的规则。','现存的是左半符。虎身有九行四十字错金铭文，涉及君王与杜地各执一半、合符发兵的制度，也记载了烽火报警的紧急例外。','看虎的行走姿态与身上的文字，想一想：凭证为什么要被分为两半？','https://www.sxhm.com/collections/detail/518.html','虎符在这里主要是什么？',['调兵凭证','玩具','酒杯'],0)
add('mandarin-gold-bowl','xian','鸳鸯莲瓣纹金碗','唐','金','金属的光，也可以读成一层层纹样。','馆方将此碗断代为唐代，并列入金银器藏品。观看时，可以从器名中的“鸳鸯”与“莲瓣”两条线索入手，辨认动植物题材如何组织在碗的曲面上。','先分清碗的整体器形与表面装饰，再找一个纹样单元；远看光泽，近看线条。','https://www.sxhm.com/collections/detail/9975.html','器名里的“莲瓣”指向什么观察线索？',['花瓣纹样','兵器长度','乐器音高'],0)
add('da-ke-ding','shanghai','大克鼎','西周中期','青铜','一件鼎，既是造型，也是文字档案。','大克鼎的腹内有长篇铭文，记载作器者克及周王的册命与赏赐。鼎身装饰的波曲纹和兽面纹，为理解西周青铜艺术提供了具体线索。','先看三足如何支撑鼎腹，再沿腹部纹样看它怎样重复。铭文请以馆方释读为准。','https://www.shanghaimuseum.cn/mu/frontend/pg/m/article/id/CI00000656','鼎内的铭文能帮助我们了解什么？',['册命与赏赐等历史信息','今天的交通实况','未来天气'],0)
add('zi-zhong-pan','shanghai','子仲姜盘','春秋早期','青铜','静止的盘里，藏着一个水生世界。','这是古代盥洗用的承水器。盘内饰有鸟、鱼、龟、蛙，立体动物能够转动；内底铭文记载了为子仲姜作盘的事情。转动结构体现了设计与铸造的巧思。','在图片或展柜外观察动物的排列。想象有水时的景象，但请勿触摸或尝试转动文物。','https://www.shanghaimuseum.net/mu/frontend/pg/m/article/id/CI00000699','这件盘原本属于哪一类器物？',['盥洗承水器','打击乐器','兵器'],0)
add('shangyang-measure','shanghai','商鞅方升','战国（秦）','青铜','把抽象的制度，变成有形的容量。','方升是古代量器。器上铭文关联商鞅时期的量制与秦统一后的诏令，是研究古代度量衡的重要实物。它的意义不只在器形，也在标准如何被记录和推行。','留意方形容量空间与侧柄，再找铭文的位置。量器可以让“标准”成为可检查的东西。','https://www.shanghaimuseum.net/resource/museum_files/show_files/20180903105852824/index.html','方升主要用来测量什么？',['容量','风速','音高'],0)
brochure='https://file.szmuseum.com/WaterMark/门户网站多媒体文件/202303201516026xhtSc.pdf'
add('lotus-bowl','suzhou','秘色瓷莲花碗','五代','青瓷','碗与托相遇，像一朵被釉色凝住的花。','此器由碗与盏托组成，是苏州博物馆馆藏珍品。馆方研究文章讨论了它从虎丘塔发现后，如何逐步被认识为秘色瓷的过程。','分别观察碗与盏托的莲花装饰，再看两者组合时轮廓如何呼应。','https://file.szmuseum.com/WaterMark/门户网站多媒体文件/academic/2019/201911_msclhwdqsjs_cheny.pdf','莲花碗由哪些部分组成？',['碗与盏托','钟与钟架','剑与盾'],0)
add('pearl-pillar','suzhou','真珠舍利宝幢','北宋','复合材料工艺','细密的装饰，需要从结构开始看。','宝幢是苏州博物馆馆藏珍品，与瑞光塔出土文物相关。与其一下寻找所有细部，不如先分辨底座、主体与顶部，理解多层结构怎样构成整体。','从下向上看层次，再挑一处连接或装饰停留。原件与复制件要以现场标识区分。',brochure,'观看宝幢适合先做什么？',['分辨整体层次','触碰装饰件','隔着展柜敲击'],0,'照片来源标题指向瑞光寺塔宝幢，描述栏误写“虎丘”；本条按馆方资料采用瑞光塔关联，不沿用该误写。照片未明确原件或复制件，不作原件承诺。')
add('silver-lian','suzhou','银奁','馆藏银器（年代见馆方展签）','银','从精巧容器，想象日常生活。','苏州博物馆的官方参观折页将银奁列入馆藏珍品。奁是一类盛放梳妆用具的容器，观看时可以关注“收纳”这一日常需求怎样变成工艺设计。','看整体轮廓、分层与配套小件，想想不同大小的物件会怎样被安排。',brochure,'“奁”通常与哪类生活用途相关？',['梳妆收纳','测量风速','城墙防御'],0)
add('goujian-sword','wuhan','越王勾践剑','春秋晚期','青铜','把目光从锋利，移向纹饰与文字。','此剑于1965年出土于湖北江陵望山一号楚墓。剑身有黑色菱形花纹，近剑格处有鸟篆铭文。馆方说明将铭文中的“鸠浅”考证为勾践。','观察剑身菱形纹与剑格的镶嵌，再找铭文所在区域。不要凭肉眼照片自行辨认全部古文字。','https://www.hbww.org.cn/zgzb/p/4694.html','剑上铭文属于哪类观察线索？',['文字与身份线索','现代生产条码','导航二维码'],0)
add('zeng-bells','wuhan','曾侯乙编钟','战国早期','青铜、木','声音的秩序，也能被铸进器物。','1978年出土于曾侯乙墓的这套编钟共六十五件，分层成组悬挂。钟与相关构件上的铭文保存了记事、标音与乐律知识。','先看大小钟如何排列，再观察钟体形状。应用导览语音不是原编钟的实录。','https://www.hbww.org.cn/zgzb/p/4695.html','这套编钟共有多少件？',['65件','5件','650件'],0)
add('zeng-zunpan','wuhan','曾侯乙尊盘','战国早期','青铜','像云，也像彼此盘绕的龙蛇。','尊盘由尊与盘两件器物组成，1978年出土于曾侯乙墓。口沿的多层镂空附饰与器身龙蛇纹，展现了复杂的结构设计。','把目光放在口沿，分辨表面花纹与支撑它的结构；复杂的视觉效果并不是一张平面图案。','https://www.hbww.org.cn/zgzb/p/6911.html','尊盘由什么组成？',['尊与盘两件器物','一件剑与剑鞘','三只碗'],0)
add('jiahu-flute','zhengzhou','贾湖骨笛','新石器时代','骨','远古的声音，先留下了孔与管。','河南舞阳贾湖遗址出土的骨笛，是研究早期音乐的重要实物。馆方资料介绍其以鸟类肢骨制成，开孔与调音反映了制作者对声音的认识。','沿骨管观察音孔的排列。音孔数量与具体音阶不能简单画等号，声音还取决于器物与演奏方式。','https://www.chnmus.net/ch/orchestra/culturalRelic/details.html?id=519116217447660468','骨笛最直接的制作材料是什么？',['骨','玻璃','金'],0)
add('fuhao-owl','zhengzhou','妇好鸮尊','商代晚期','青铜','把鸟的形象，转化为稳固的器物。','鸮尊出土于安阳殷墟妇好墓，因内壁“妇好”铭文得名。双足与下垂的宽尾构成三点支撑，猫头鹰形象与盛酒器的功能结合。','看双足与尾巴怎样共同支撑器身，再找器物开口与盖的位置。同墓出土的近似鸮尊分藏不同馆，不混作同一件。','https://www.chnmus.net/ch/collection/treasure/details.html?id=508163196212274341','鸮尊的尾巴还起到了什么作用？',['帮助支撑器身','吹奏旋律','测量容量标准'],0)
add('lotus-crane-hu','zhengzhou','莲鹤方壶','春秋','青铜','厚重的青铜上，一只鹤正展开翅膀。','壶盖上有莲瓣形装饰，中间立着展翅的鹤。器身还有龙形耳与立体小兽。1923年河南新郑出土的一对莲鹤方壶，分别藏于河南博物院与故宫博物院。','从底部承托的小兽一直看到顶部的鹤，感受重量与向上动势之间的关系；本页照片为河南博物院藏器。','https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zpjc/articlea46f687a6905473b802616ef859d14de.html','壶盖顶部站立的是什么？',['鹤','马','鱼'],0)
hunan='https://web.hnmuseum.com/en/content/changsha-mawangdui-han-dynasty-tombs-exhibition'
add('gauze-gown','changsha','直裾素纱襌衣','西汉','丝织品','轻薄，不等于简单。','这件出自马王堆一号汉墓的纱衣，是理解汉代丝织工艺的重要实物。“襌”读作dān，指没有衬里的单衣。观察轻纱与缘边，可以看到不同织物各司其职。','先看领口、袖口与衣身的差异，再观察纱的透明感。用途存在讨论，不把某种穿法当作唯一答案。',hunan,'“襌衣”的“襌”在这里是什么意思？',['没有衬里的单衣','专供僧人穿的禅衣','厚棉袄'],0)
add('mawangdui-banner','changsha','马王堆一号墓T形帛画','西汉','绢帛、设色','一张帛画，展开一个关于生命的世界。','画作上宽下窄，呈T形。沿着画面上下的层次，可观察天上、人间与地下的形象安排。这是理解汉代观念与绘画的重要材料，具体图像解释仍需结合学术研究。','先沿中轴从上到下看构图，再选择一个人物或动物追问其位置；本页对应一号墓，不与三号墓帛画混淆。',hunan,'本条对应哪一座墓的帛画？',['马王堆一号墓','马王堆三号墓','曾侯乙墓'],0)
add('black-coffin','changsha','马王堆一号墓黑地彩绘棺','西汉','漆木','黑色为底，让云气与生灵流动。','黑地彩绘棺是马王堆一号墓套棺中的一层，馆方介绍其黑色外表绘有云纹与多种奇异形象。漆色、线条与图像共同表达了当时人们对生命与另一个世界的想象。','先用眼睛跟随一条云纹，再辨认纹样间的动物与神异形象。它与朱地彩绘棺是不同的层，不能混称。',hunan,'本条黑地彩绘棺与朱地彩绘棺是什么关系？',['不同的套棺层','同一张照片的滤镜','同一件瓷器'],0)
M=[]
for mid,v in S.items():
 city,roman,name,full,kind,official,address,theme,intro=v
 ids=[a['id'] for a in A if a['museum']==mid]
 M.append(dict(id=mid,city=city,roman=roman,name=name,fullName=full,kind=kind,cover=mid+'-exterior',gallery=[mid+'-exterior']+ids,theme=theme,quote='把一次旅行，变成一次认真观看。',intro=intro,address=address,duration='建议 90—120 分钟（可按体力缩短）',tags=['文物','城市漫游','观察导览'],crafts=[],artifacts=ids,official=official,sources=[{'title':name+'官方网站','url':official}]+[a['source'] for a in A if a['museum']==mid],tips=['先从馆方渠道确认到访馆区、预约要求与当天开放情况。','本应用提供馆藏知识，不保证资料中每件文物当天在展。','顺序为主题观看建议，不代表馆内真实位置；请结合现场指引，累了随时休息。'],chapters=[{'title':'初见 · '+city+'的时间入口','text':intro+'今天可以先选择一件感兴趣的文物，从整体轮廓看起，再读展签。这里的推荐是主题观看线索，不代表馆内实际展陈位置。','audio':False},{'title':'细看 · 选一处细节','text':'不必急着看完所有展厅。先找材料、纹样与用途之间的关系，再将观察与标签文字相互印证。遇到不知道的名字，可以记下展签，用观物继续查阅相关条目。','audio':False},{'title':'带走 · 一个自己的问题','text':'结束参观前，回想今天最让你愿意停留的一件文物。它的哪一个细节改变了你的第一印象？写进手记，也可以把这个问题交给随行助手，带着来源继续探索。','audio':False}]))
Path('research/expansion-content.json').write_text(json.dumps({'museums':M,'artifacts':A},ensure_ascii=False,indent=2),encoding='utf8')
print(len(M),'museums',len(A),'artifacts')
